def admit(active, waiting, budget, slots):
    # A booking that exceeds the total budget is invalid, even if FIFO admission
    # would stop before ever reaching it.
    for value in waiting:
        if value > budget:
            raise ValueError(f"booking {value} exceeds total budget {budget}")

    admitted = []
    used = sum(active)
    for i, value in enumerate(waiting):
        if len(admitted) < slots and used + value <= budget:
            admitted.append(value)
            used += value
        else:
            # FIFO stop: the first booking that does not fit (either because of
            # the remaining budget or the slots) and everything after it remain.
            return admitted, waiting[i:]
    return admitted, []

def admit(active, waiting, budget, slots):
    # A booking that exceeds the total budget is invalid, even if FIFO admission
    # would stop before ever reaching it.
    for value in waiting:
        if value > budget:
            raise ValueError(f"booking {value} exceeds total budget {budget}")

    admitted = []
    used = sum(active)
    free = slots - len(active)  # slots are shared with the already-active bookings
    for i, value in enumerate(waiting):
        if free > 0 and used + value <= budget:
            admitted.append(value)
            used += value
            free -= 1
        else:
            # FIFO stop: the first booking that does not fit (either because of
            # the remaining budget or the free slots) and everything after it.
            return admitted, waiting[i:]
    return admitted, []

